from pathlib import Path
from html import escape
from PIL import Image
from data import nav, advantages, materials
root=Path(__file__).resolve().parents[1]; site=root/'site'
imgdir=site/'assets/img'; imgdir.mkdir(parents=True,exist_ok=True)
for source, target in [('1.2.jpg','rings.jpg'),('plaque.jpg','viton-certificate.jpg')]:
    im=Image.open(root/'src/assets/img/images'/source)
    if source=='1.2.jpg': im=im.crop((0,0,235,216))
    im=im.convert('RGB')
    im.save(imgdir/target, quality=82, optimize=True)
def img(name, alt, w, h, eager=False):
    return f'<img src="/assets/img/{name}" alt="{alt}" width="{w}" height="{h}" '+('fetchpriority="high"' if eager else ('loading="eager"' if (imgdir/name).stat().st_size < 30000 else 'loading="lazy"'))+'>'
def groove_table(title, depths):
    rows=zip(['011-050','111-178','210-284','325-395','425-475'],['.070','.103','.139','.210','.275'],depths,['.094','.141','.188','.279','.375'],['.016','.023','.039','.047','.059'],['.006','.007','.007','.009','.009'])
    return '<h3>'+title+'</h3><p class="scroll-cue">Scroll table horizontally →</p><div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in ['Part No.*','Cross section W','Groove depth '+('E' if title.startswith('Radial') else 'E₁')+' + .002','Groove width '+('F' if title.startswith('Radial') else 'F₃')+' + .008','Radius R₁','Diametrical clearance Smax'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def ul(items): return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def link(text,url,cls=''): return f'<a class="{cls}" href="{url}">{text}</a>'
def layout(title,desc,path,body):
    menu=''.join(f'<li><a href="{url}"'+(' aria-current="page"' if url==path else '')+f'>{name}</a>'+ ('<ul class="subnav"><li><a href="/product-information/#sizes">Sizes</a></li><li><a href="/product-information/#materials">Materials</a></li><li><a href="/product-information/#installation">Installation and service life</a></li></ul>' if url == '/product-information/' else '')+'</li>' for name,url in nav)
    back = '<div class="wrap back"><a href="/">← Home</a></div>' if path != '/' else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex"><title>{title} | Has-Mor Industries</title><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:title" content="{title} | Has-Mor Industries"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="https://has-mor.com{path}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/red-hat-display-700.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/css/site.css"><script defer src="/assets/js/site.js"></script><script type="application/ld+json">{{"@context":"https://schema.org","@type":"Organization","name":"Has-Mor Industries, Inc.","url":"https://has-mor.com/","telephone":"570-383-0185","faxNumber":"570-489-3560","email":"Info@Has-Mor.com","address":{{"@type":"PostalAddress","postOfficeBoxNumber":"111","addressLocality":"Dunmore","addressRegion":"PA","postalCode":"18512","addressCountry":"USA"}}}}</script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Has-Mor Industries home"><img src="/assets/img/has-mor-logo.png" width="210" height="152" alt="Has-Mor Industries"></a><nav id="navigation" aria-label="Main navigation"><button class="menu-close" type="button" aria-label="Close menu">Close</button><ul>{menu}</ul></nav><a class="button header-quote" href="/request-a-quote/">Request a quote</a><button class="menu-toggle" type="button" aria-controls="navigation" aria-expanded="false">Menu</button></div></header><main id="main">{back}{body}</main><footer><div class="wrap footer-grid"><div><a class="footer-brand" href="/"><img src="/assets/img/has-mor-logo.png" width="210" height="152" alt="Has-Mor Industries"></a></div><div><p>Has-Mor Industries<br>P.O. Box 111<br>Dunmore, PA 18512, U.S.A.</p></div><div><p><a href="tel:5703830185">570-383-0185</a><br>Fax: 570-489-3560<br><a href="mailto:Info@Has-Mor.com">Info@Has-Mor.com</a></p></div></div><div class="wrap legal">Teflon® is a registered Trademark of DuPont.</div></footer></body></html>'''
def hero(title,desc='',dark=False): return f'<section class="page-hero {"dark" if dark else ""}"><div class="wrap"><h1>{title}</h1>{f"<p>{desc}</p>" if desc else ""}</div></section>'
def field(label,name,typ='text',required=False,auto='',area=False):
    req=' required' if required else ''; ac=f' autocomplete="{auto}"' if auto else ''
    control=f'<textarea id="{name}" name="{name}" rows="5"{req}></textarea>' if area else f'<input id="{name}" name="{name}" type="{typ}"{req}{ac}>'
    return f'<div class="field"><label for="{name}">{label}</label>{control}</div>'
def form(quote=False):
    fields=field('Name','name',required=True,auto='name')+field('Company','company',auto='organization')+field('Email','email','email',True,'email')+field('Phone','phone','tel',auto='tel')
    if quote:
        fields+=field('Size / AS568 dash no. or dimensions','size',required=True)
        fields+='<div class="field"><label for="jacket">Jacket</label><select id="jacket" name="jacket" required><option value="">Select</option><option>FEP</option><option>PFA</option></select></div>'+field('Core material','core')+'<div class="field"><label for="section">Cross-section</label><select id="section" name="section"><option value="">Select</option><option>Solid</option><option>Hollow</option><option>Square</option></select></div>'+field('Quantity','quantity')+field('Application / media / temperature','application',area=True)
    fields+=field('Message','message',area=True,required=not quote)
    return '<!-- Replace the mailto handler with a production form endpoint here. --><form data-mail-form data-subject="'+('Quote request' if quote else 'Contact inquiry')+'"><div class="form-grid">'+fields+'</div><button class="button" type="submit">'+('Request a quote' if quote else 'Send message')+'</button><p class="status" role="status" aria-live="polite"></p></form>'
home='<section class="page-hero dark home-hero"><div class="wrap hero-grid"><div><h1>FEP and PFA encapsulated o&#8209;rings</h1><p>Precision encapsulated o-rings manufactured to strict industry tolerances using our Documented Quality Assurance system.</p><div class="actions">'+link('Request a quote','/request-a-quote/','button light')+link('Product information','/product-information/','text-link')+'</div></div>'+img('rings.jpg','Red and black encapsulated o-rings',235,216,True)+'</div></section>'
profiles={
    'solid-core':'<circle cx="60" cy="60" r="36" fill="#13202b"/><circle cx="60" cy="60" r="39" fill="none" stroke="#c23a2b" stroke-width="1.5"/>',
    'hollow-core':'<circle cx="60" cy="60" r="36" fill="none" stroke="#13202b" stroke-width="2"/><circle cx="60" cy="60" r="39" fill="none" stroke="#c23a2b" stroke-width="1.5"/><circle cx="60" cy="60" r="21" fill="none" stroke="#13202b" stroke-width="2"/>',
    'square-cross-sections':'<rect x="25" y="25" width="70" height="70" fill="#13202b"/><rect x="22" y="22" width="76" height="76" fill="none" stroke="#c23a2b" stroke-width="1.5"/>',
    'encapsulated-cord':'<path d="M18 42h84v36H18z" fill="#13202b"/><path d="M18 39h84v42H18" fill="none" stroke="#c23a2b" stroke-width="1.5"/>',
}
def product_art(anchor):
    if anchor == 'custom-shapes': return img('custom-rings-alpha.png','Custom shaped o-rings',418,129)
    return '<svg viewBox="0 0 120 120" aria-hidden="true" focusable="false">'+profiles[anchor]+'</svg>'
home+='''<section class="section pale products-section"><div class="wrap"><h2>Products</h2><div class="product-grid">'''+''.join(f'<a class="product {anchor}" href="/product-information/#{anchor}"><div class="product-art">{product_art(anchor)}</div><span>{name}</span></a>' for name,anchor in [('Solid core','solid-core'),('Hollow core','hollow-core'),('Square cross sections','square-cross-sections'),('Encapsulated cord','encapsulated-cord'),('Custom shapes and sizes','custom-shapes')])+'''</div></div></section>'''
about=hero('About Has-Mor')+'''<section class="section"><div class="wrap narrow"><p class="intro">Has-Mor Industries, Inc. is a manufacturer of FEP and PFA encapsulated o-rings.</p><p>Our precision encapsulated o-rings are manufactured to strict industry tolerances using our Documented Quality Assurance system. Our engineering and manufacturing skills meet custom or proprietary requirements.</p><p>We produce solid core, hollow core, square cross sections, encapsulated cord, as well as custom shapes and sizes.</p><p>Has-Mor Industries, Inc. is an authorized licensee for DuPont Performance Elastomers Genuine Viton® with Viton® Tracer™ Technology.</p>'''+img('viton-certificate.jpg','Viton official licensee certificate',400,302)+'''<p>Our commitment is to customer care and satisfaction, addressing all inquiries with priority and dedication.</p></div></section>'''
product=hero('Product information')+'''<div class="wrap content-layout"><aside id="section-links"><nav aria-label="On this page"><a href="#how">How they work</a><a href="#advantages">Advantages</a><a href="#materials">Materials</a><a href="#sizes">Sizes</a><a href="#installation">Installation and service life</a><a href="/assets/docs/Product-Information.pdf">Download product PDF ↗</a></nav></aside><div class="content"><section id="how"><h2>How encapsulated o-rings work</h2><p>Encapsulated o-rings are double-action sealing elements. The seal is provided by the FEP or PFA encapsulation; the elastomer o-ring (fluorocarbon rubber, silicone, etc.) serves as an elastic pretension element exerting a permanent and uniform pressure against the mating surface. The FEP or PFA jacket encases the elastomer o-ring without seams.</p><p>Encapsulated o-rings are used wherever conventional elastomer o-rings cannot be used due to inadequate chemical resistance. Combining the FEP or PFA jacket with core materials provides elasticity and chemical resistance for uses in the chemical industry, medical technology, petrochemical, food industries and similar industrial uses.</p><p>Encapsulated o-rings are primarily used as static seals (axial and radial) for lids and covers, flanges, disks, etc. When subject to significant strains and stresses (speed and pressure), the seal can also be used for dynamic sealing for pistons, rods, valve spindles, and mechanical seals. When greater stress is anticipated, preliminary experiments are recommended.</p><div class="figure-grid"><figure>'''+img('mechanical-seal-alpha.png','Typical mechanical seal drawing',177,200)+'''</figure><figure>'''+img('valve-stem-alpha.png','Typical valve stem drawing',130,232)+'''</figure></div></section><section id="advantages"><h2>Advantages</h2>'''+ul(advantages)+'''</section><section id="materials"><h2>Materials</h2><p>The materials below are used to produce our standard product line. Specialty compounds are used occasionally depending upon overall demand or special customer needs.</p>'''
intros=['FEP offers an excellent combination of properties.','PFA is a premium resin preferred when extended service is required in hostile environments involving chemical, thermal, and mechanical stress.','VITON® is a fluoroelastomer compound which offers exceptional mechanical properties and low compression set. Has-Mor Industries, Inc. is an authorized licensee for DuPont Performance Elastomers Genuine Viton® with Viton® Tracer™ Technology.','Silicone Elastomer possesses mechanical properties similar to fluoroelastomer compounds but with slightly lower compression set resistance.','EPDM is a peroxide-cured elastomer.']
for (name,items),intro in zip(materials.items(),intros): product+=f'<div class="material"><h3>{name}</h3><p>{intro}</p>{ul(items)}</div>'
product+='''<p>The temperature ranges advised are limit values and must always be considered in connection with the medium to be sealed and the operating pressure. The permissible temperature for extended operation is always lower than the upper limit values.</p><p class="note">VITON® is a registered Trademark of DuPont Performance Elastomers. VITON® Tracer™ is a Trademark of DuPont Performance Elastomers.</p></section><section id="sizes"><h2>Sizes</h2><p>We produce <span id="solid-core">solid core</span>, <span id="hollow-core">hollow core</span>, <span id="square-cross-sections">square cross sections</span>, <span id="encapsulated-cord">encapsulated cord</span>, as well as custom shapes and sizes to meet your needs.</p><p>The dimensions of encapsulated o-rings are specified by the inside diameter (ID) and the cross section (W). Encapsulated o-rings are available in five standard cross sections:</p><div class="table-wrap" tabindex="0"><table><thead><tr><th scope="col">O-Ring Section (W*)</th><th scope="col">O-ring AS-568A</th></tr></thead><tbody>'''+''.join(f'<tr><td>{a}</td><td>{b}</td></tr>' for a,b in [('.070” (1.78 mm)','O-rings -011 to -050'),('.103” (2.62 mm)','O-rings -111 to -178'),('.139” (3.53 mm)','O-rings -210 to -284'),('.210” (5.33 mm)','O-rings -325 to -395'),('.275” (7.00 mm)','O-rings -425 to -475')])+'''</tbody></table></div><p>* Cross section W in accordance to AS 568A.</p><p>The finished cross section of an encapsulated o-ring is the same width as a standard o-ring in the same size. Besides the most common standard ID/CS range listed above, a range of nonstandard diameters is also available in the standard cross sections. Other metric and nonstandard cross sections are also available from .063" (1.6mm) through .787" (20mm).</p>'''+img('dimensions-alpha.png','O-ring inside diameter ID and cross section W',206,64)+'''<h3 id="custom-shapes">Custom shapes and sizes</h3>'''+img('custom-rings-alpha.png','Custom shaped o-rings',418,129)+'''<p>We can work with you to meet proprietary needs. To determine feasibility and minimum order and production requirements, please <a href="/contact/">contact us</a>.</p></section><section id="installation"><h2>Installation and service life</h2><p>In general, the same regulations apply to installation of encapsulated o-rings as for conventional elastomer o-rings. Due to FEP encapsulation, these sealing rings can neither be squeezed into place as easily as purely elastic o-rings, nor do they contract as easily after stretching. To avoid unnecessary distortion of the encapsulation when the ring is installed, a split groove is recommended for radial-static and dynamic installation.</p><p>When used for external seal application (e.g. pistons), the encapsulated o-rings must be stretched out and then put back in shape. For installation recommendations, please contact us.</p><p>For internal seal application (e.g. rods), encapsulated o-rings with increasing diameter can be installed. For installation of o-rings with smaller diameters, the possibility of using closed grooves should be investigated in each particular case.</p><p>The sealing ring must never be forced into the groove by buckling it, since this can spoil the sealing function. In such cases, a split groove must be used.</p><p>Encapsulated o-rings are installed in rectangular grooves. For operating pressures higher than approximately 50 bar, additional backup rings can be an advantage. This prevents the FEP encapsulation from being buckled or damaged by sharp groove edges or narrow corner angles.</p><div class="figure-row">'''+img('static-installation-alpha.png','Static installation drawing',223,178)+img('dynamic-installation-alpha.png','Dynamic installation drawing',205,190)+'''</div>'''+groove_table('Radial — Dynamic/static',['.057','.088','.122','.185','.240'])+groove_table('Axial — static',['.047','.075','.106','.169','.228'])+'''<h3>Function and service life (surface roughness)</h3><p class="scroll-cue">Scroll table horizontally →</p><p>The function and service life of a seal depends on the quality and character of the surface.</p><div class="table-wrap" tabindex="0"><table><thead><tr><th scope="col">Application</th><th scope="col">Surface</th><th scope="col">Roughness</th></tr></thead><tbody><tr><td>Radial—Dynamic and Static</td><td>Bore/Rod</td><td>Ra = 0.05-0.6 µm [Rmax = .02-2.5 µm]</td></tr><tr><td>Radial—Dynamic and Static</td><td>Groove Surface, Static</td><td>Ra ≤ 2.5 µm [Rmax ≤ 10 µm]</td></tr><tr><td>Radial—Dynamic and Static</td><td>Groove Surface, Dynamic with pulsating pressures</td><td>Ra ≤ 1.5 µm [Rmax ≤ 6 µm]</td></tr><tr><td>Axial-Static</td><td>Seal and Groove Surface</td><td>Ra ≤ 2.5 µm [Rmax ≤ 10 µm]</td></tr><tr><td>Axial-Static</td><td>with Pulsating Pressures</td><td>Ra ≤ 1.5 µm [Rmax ≤ 6 µm]</td></tr></tbody></table></div><p>For more information on installing your o-rings, <a href="/contact/">contact us</a>.</p></section></div></div>'''
# Place selection details immediately after the introductory explanation.
start=product.index('<section id="sizes">')
end=product.index('<section id="installation">', start)
sizes=product[start:end]
product=product[:start]+product[end:]
position=product.index('<section id="advantages">')
product=product[:position]+sizes+product[position:]
product=product.replace('<a href="#advantages">Advantages</a><a href="#materials">Materials</a><a href="#sizes">Sizes</a>', '<a href="#sizes">Sizes</a><a href="#advantages">Advantages</a><a href="#materials">Materials</a>')
product=product.replace('<p>We produce <span id="solid-core">solid core</span>, <span id="hollow-core">hollow core</span>, <span id="square-cross-sections">square cross sections</span>, <span id="encapsulated-cord">encapsulated cord</span>, as well as custom shapes and sizes to meet your needs.</p>', '<ul class="size-types"><li id="solid-core">Solid core</li><li id="hollow-core">Hollow core</li><li id="square-cross-sections">Square cross sections</li><li id="encapsulated-cord">Encapsulated cord</li><li id="custom-shapes">Custom shapes and sizes</li></ul>')
product=product.replace('<div class="table-wrap" tabindex="0"><table><thead><tr><th scope="col">O-Ring Section (W*)', '<div class="dimensions-layout"><div class="table-wrap" tabindex="0"><table><thead><tr><th scope="col">O-Ring Section (W*)', 1)
dim=img('dimensions-alpha.png','O-ring inside diameter ID and cross section W',206,64)
product=product.replace('</tbody></table></div><p>* Cross section W', '</tbody></table></div>'+dim+'</div><p>* Cross section W', 1)
product=product.replace(dim+'<h3 id="custom-shapes">Custom shapes and sizes</h3>', '<h3>Custom shapes and sizes</h3><div class="custom-layout">', 1)
product=product.replace('please <a href="/contact/">contact us</a>.</p></section><section id="installation">', 'please <a href="/contact/">contact us</a>.</p></div></section><section id="installation">', 1)
product=product.replace('</section><section id="', '<p class="return-sections"><a href="#section-links">↑ Product sections</a></p></section><section id="')
ordering=hero('Ordering information')+'''<section class="section"><div class="wrap content"><h2>Order procedures and call-outs</h2><p>The following is an example of order procedures and call-outs:</p><div class="example"><h3>Encapsulated O-Ring</h3><p>Standard ARP Size -214<br>Material: Fluorocarbon Rubber</p></div><dl class="callout"><div><dt>T</dt><dd>FEP encapsulated O-Ring</dd></div><div><dt>V</dt><dd>O-Ring material</dd></div><div><dt>214</dt><dd>O-Ring size</dd></div></dl><p><a href="/request-a-quote/">Request a quote</a></p><h3>Material codes</h3><div class="table-wrap" tabindex="0"><table><thead><tr><th scope="col">Code</th><th scope="col">Material</th></tr></thead><tbody><tr><td>T</td><td>FEP Material</td></tr><tr><td>V</td><td>Fluorocarbon Rubber</td></tr><tr><td>S</td><td>Silicone Rubber</td></tr></tbody></table></div><p><a href="/assets/docs/Ordering-Information.pdf">Download ordering information PDF ↓</a></p><h2>Disclaimer</h2><p>Because we cannot foresee or control the varied conditions under which this information and our o-rings may be used, we do not guarantee the applicability or accuracy of this information or the suitability of our o-rings in any specific situation. Users should conduct their own tests to determine the suitability of our o-rings for their specific purposes. As we do not manufacture the actual compounds used in the production of o-rings, we cannot verify the information provided by the actual manufacturers of the compounds themselves nor guarantee the performance against desired results.</p></div></section>'''
quote=hero('Request a quote')+'<section class="section"><div class="wrap form-layout"><div><p><a href="tel:5703830185">570-383-0185</a><br><a href="mailto:Info@Has-Mor.com">Info@Has-Mor.com</a></p></div>'+form(True)+'</div></section>'
contact=hero('Contact')+'<section class="section"><div class="wrap form-layout contact-layout"><div><h2>Has-Mor Industries</h2><p>P.O. Box 111<br>Dunmore, PA 18512, U.S.A.</p><p>Tel: <a href="tel:5703830185">570-383-0185</a><br>Fax: 570-489-3560<br>Email: <a href="mailto:Info@Has-Mor.com">Info@Has-Mor.com</a></p></div>'+form()+'</div></section>'
pages=[('/','Home','Manufacturer of FEP and PFA encapsulated o-rings.',home),('/about/','About','Has-Mor Industries manufactures encapsulated o-rings using a Documented Quality Assurance system.',about),('/product-information/','Product information','Materials, sizes, installation and service life for encapsulated o-rings.',product),('/ordering-information/','Ordering information','Order procedures and call-outs for encapsulated o-rings.',ordering),('/request-a-quote/','Request a quote','Request a quote for encapsulated o-rings.',quote),('/contact/','Contact','Contact Has-Mor Industries in Dunmore, Pennsylvania.',contact)]
for path,title,desc,body in pages:
    target=site/path.lstrip('/'); target.mkdir(parents=True,exist_ok=True); (target/'index.html').write_text(layout(title,desc,path,body).replace('</a><a', '</a> <a').replace('</a><button', '</a> <button'))
(site/'404.html').write_text(layout('Page not found','Page not found.','/404.html',hero('Page not found')+'<section class="section"><div class="wrap"><a class="button" href="/">Return home</a></div></section>').replace('</a><a', '</a> <a').replace('</a><button', '</a> <button'))


# Preview-only "Keep this site" subscribe button, added to every page after the build.
# Set PREVIEW_SUBSCRIBE_URL = '' in src/data.py and rebuild to remove it.
from data import PREVIEW_SUBSCRIBE_URL
def add_preview_subscribe():
 import re
 from html import escape as esc
 site_dir=Path(__file__).resolve().parent.parent/'site'
 css=("a.preview-subscribe{position:fixed;right:max(20px,calc(env(safe-area-inset-right) + 12px));bottom:max(20px,calc(env(safe-area-inset-bottom) + 12px));z-index:19;display:inline-flex;align-items:center;min-height:66px;padding:0 27px;border-radius:999px;background:#a82019;color:#fff;font:700 22.5px/1.1 'Red Hat Text',sans-serif;letter-spacing:.01em;text-transform:none;text-decoration:none;white-space:nowrap;box-shadow:0 9px 27px rgba(0,0,0,.22);transition:background-color .15s,opacity .2s,visibility .2s}"
  "a.preview-subscribe:hover{background:#8f261d;color:#fff;text-decoration:none}"
  "a.preview-subscribe:focus-visible{background:#a82019;color:#fff;outline:3px solid #a82019;outline-offset:3px;box-shadow:0 0 0 3px #fff,0 6px 18px rgba(0,0,0,.22)}"
  "a.preview-subscribe.is-tucked,body:has(header [aria-expanded=\"true\"]) a.preview-subscribe{opacity:0;visibility:hidden}"
  "@media (max-width:760px){a.preview-subscribe{right:max(12px,calc(env(safe-area-inset-right) + 8px));bottom:max(12px,calc(env(safe-area-inset-bottom) + 8px));min-height:60px;padding:0 21px;font-size:21px}}"
  "footer:last-of-type::after{content:\"\";display:block;height:88px}"
  "@media (prefers-reduced-motion:reduce){a.preview-subscribe{transition:none}}")
 js=""
 from keep import build_keep
 build_keep(site_dir,PREVIEW_SUBSCRIBE_URL)
 for page in site_dir.rglob('*.html'):
  if page==site_dir/'keep'/'index.html': continue
  html=re.sub(r'<!-- preview-subscribe -->.*?<!-- /preview-subscribe -->','',page.read_text(),flags=re.S)
  if PREVIEW_SUBSCRIBE_URL:
   html=html.replace('</head>','<!-- preview-subscribe --><style>'+css+'</style><!-- /preview-subscribe --></head>',1)
   html=html.replace('</body>','<!-- preview-subscribe --><a class="preview-subscribe" href="/keep/" aria-label="Upgrade my website: see how to switch to this new site">Upgrade my website</a><script>'+js+'</script><!-- /preview-subscribe --></body>',1)
  page.write_text(html)
add_preview_subscribe()
